// The nine valence artworks — the creature-and-fossil line art the valence fan
// inks inside each stone. Ported verbatim from the iOS bundle
// (`apps/ios/Pebbles/Resources/ValenceArt/*.svg`), which
// `apps/ios/Scripts/valence-art-to-svg.mjs` generates from the source vector
// PDFs. Do not re-derive them here: the converter's header documents a
// verification step (ink distribution against the PDF, straight vs vertically
// flipped) that an eyeball check misses, and iOS owns it.
//
// Each artwork holds two kinds of path, and the difference is load-bearing:
//
// - `strokes` are centerlines carrying the width the PDF drew them with. They
//   go through `wobbleGlyphInk`, the leaky-outline pass a carved glyph gets.
//   Their own widths rather than the uniform `OUTLINE_WIDTH` a real pebble
//   traces at — the box is ~190 units and the detail is fine, so the pebble
//   weight merges it.
// - `regions` are already-filled shapes (the fossil's spiral, one per
//   artwork). They go through `wobbleBackdrop`, which displaces a region's
//   contours. Ink a filled spiral as a centerline and it fills in solid.
//
// Mirrors `pebble-outlines.ts`'s TABLE[size][polarity] shape.

import type { Size, Polarity } from "./pebble-geometry"

/** A centerline to be inked at `width`, in the artwork's own viewBox units. */
export type ValenceArtStroke = { width: number; d: string }

/** An already-filled region, displaced rather than inked. */
export type ValenceArtRegion = { fillRule: "evenodd" | "nonzero"; d: string }

export type ValenceArtwork = {
  /** viewBox dims; the artwork's own space, ~190 units on the long side. */
  width: number
  height: number
  strokes: ValenceArtStroke[]
  regions: ValenceArtRegion[]
}

